/* Search and filter behavior — generated by sitereal. A hand edit here is kept: sitereal asks before writing over it. */
(() => {
  if (window.__siterealSearch) { window.__siterealSearch.scan(); return; }
  /* a page in another language names its own index in its head */
  const INDEX_URL = document.querySelector('meta[name="search-index"]')?.getAttribute('content') || '/search-index.json';
  const MARKS = /[̀-ͯ]/g;
  const LETTER = /[\p{L}\p{N}]/u;
  const fold = (s, accents) => {
    let t = String(s == null ? '' : s).toLowerCase();
    if (accents !== false) t = t.normalize('NFD').replace(MARKS, '');
    return t;
  };
  const words = (s, accents) => fold(s, accents).match(/[\p{L}\p{N}]+/gu) || [];
  const esc = (s) => String(s).replace(/&/g, '&amp;').replace(/</g, '&lt;').replace(/>/g, '&gt;').replace(/"/g, '&quot;');
  let seq = 0;
  const uid = (p) => 'sitereal-' + p + '-' + (seq += 1);
  const typing = (el) => !!el && (el.isContentEditable || /^(INPUT|TEXTAREA|SELECT)$/.test(el.tagName));
  const markup = (html) => { const t = document.createElement('template'); t.innerHTML = html; return t.content; };
  /* where a result goes: the row is a link, or holds one */
  const hrefOf = (el) => el.href || (el.querySelector('a[href]') || {}).href || '';
  const SP = (n) => '[data-search-part="' + n + '"]';
  const FP = (n) => '[data-filter-part="' + n + '"]';

  /* ================================================================ filter */

  const keyAttr = (k) => 'data-filter-' + String(k).toLowerCase().replace(/[^a-z0-9]+/g, '-').replace(/^-+|-+$/g, '');
  const split = (v) => (v ? String(v).split('|').filter((x) => x !== '') : []);
  const byLabel = (labels) => (a, b) => String(labels.get(a)).localeCompare(String(labels.get(b)), undefined, { numeric: true, sensitivity: 'base' });

  function initFilter(root) {
    if (root.hasAttribute('data-filter-ready')) return;
    root.setAttribute('data-filter-ready', '');
    const own = (sel) => [...root.querySelectorAll(sel)].filter((el) => el.closest(FP('filter')) === root);
    const n = (seq += 1);

    const facets = own(FP('facet')).map((el) => {
      const type = el.getAttribute('data-facet-type') || 'checkbox';
      return {
        el, type,
        key: (el.getAttribute('data-facet') || '').trim(),
        multi: type === 'checkbox' || (type === 'buttons' && el.hasAttribute('data-facet-multiple')),
        all: el.getAttribute('data-facet-match') === 'all',
        counts: el.getAttribute('data-facet-counts') !== 'off',
        empty: el.getAttribute('data-facet-empty') || 'disable',
        sort: el.getAttribute('data-facet-sort') || 'label',
        allLabel: el.getAttribute('data-facet-all') || 'All',
        selected: new Set(), labels: new Map(), options: new Map(), control: null,
        /* a range's own: what is typed into each end, and what the rows hold */
        range: type === 'range', from: '', to: '', kind: '', lo: '', hi: '', fields: null,
      };
    }).filter((f) => f.key);

    /* The sorts: every select a sort part holds, all of them one state. */
    const sorts = [...new Set([
      ...own(FP('sort-select')),
      ...own(FP('sort')).map((w) => w.querySelector('select')),
    ])].filter(Boolean);
    const sortKeys = [...new Set(sorts.flatMap((sel) => [...sel.options].map((o) => o.value.split(':')[0]).filter(Boolean)))];
    let sort = '';

    const info = own('[data-filter-item]').map((el, i) => {
      const values = {};
      for (const f of facets) {
        const vals = split(el.getAttribute(keyAttr(f.key)));
        values[f.key] = vals;
        if (f.range) continue;
        const labels = split(el.getAttribute(keyAttr(f.key) + '-label'));
        vals.forEach((v, k) => { if (!f.labels.has(v)) f.labels.set(v, labels[k] || v); });
      }
      /* What a sort compares: a taxonomy's names where the row carries them,
         the value otherwise. */
      const by = {};
      for (const k of sortKeys) by[k] = (el.getAttribute(keyAttr(k) + '-label') ?? el.getAttribute(keyAttr(k)) ?? '').trim();
      const also = (el.getAttribute('data-filter-text') || '').replace(/<[^>]*>/g, ' ');
      /* i is where the Loop put it — what "as delivered" goes back to */
      return { el, i, values, by, text: fold(el.textContent + ' ' + also) };
    });

    /* A search inside the filter narrows it — unless it says it searches
       the site, and then it is the site search's. */
    const inputs = own(SP('input')).filter((i) => {
      const s = i.closest(SP('search'));
      return !s || s.getAttribute('data-search-scope') !== 'site';
    });
    /* the sentence for many: parked by the build while the text is the number
       it worked out (data-count-many), or the text as written */
    const counts = own(FP('count')).map((el) => ({ el, many: (el.hasAttribute('data-count-many') ? el.getAttribute('data-count-many').trim() : el.textContent.trim()) || '# results' }));
    const empties = own(FP('empty'));
    const resets = own(FP('reset'));
    /* on while it is there — and off when it says "false", which is how a
       hand or an agent writes "off" and which read as on */
    const url = root.hasAttribute('data-filter-url') && root.getAttribute('data-filter-url') !== 'false';
    let q = '';

    const textOk = (it, terms) => terms.every((t) => it.text.includes(t));
    const isOn = (f) => (f.range ? f.from !== '' || f.to !== '' : f.selected.size > 0);
    /* A number is compared as a number; a date by its day, as written — the
       first ten characters of an ISO date, which is the day in the data's own
       time zone rather than the visitor's. */
    const inRange = (f, v) => {
      if (f.kind === 'number') {
        const x = Number(v);
        return v !== '' && Number.isFinite(x) && (f.from === '' || x >= Number(f.from)) && (f.to === '' || x <= Number(f.to));
      }
      const d = String(v).slice(0, 10);
      return (f.from === '' || d >= f.from) && (f.to === '' || d <= f.to);
    };
    const facetOk = (it, f) => {
      if (!isOn(f)) return true;
      const vals = it.values[f.key] || [];
      if (f.range) return vals.some((v) => inRange(f, v));
      return f.all ? [...f.selected].every((v) => vals.includes(v)) : vals.some((v) => f.selected.has(v));
    };

    function toggle(f, v, on) {
      if (v === '') f.selected.clear();
      else if (f.multi) {
        const now = on === undefined ? !f.selected.has(v) : on;
        if (now) f.selected.add(v); else f.selected.delete(v);
      } else if (f.type === 'buttons' && f.selected.has(v)) f.selected.clear();
      else f.selected = new Set([v]);
      update();
    }

    /* Controls already in the box: written by somebody, or by the build from
       the rows — those wear the parts this script would have made, so they are
       counted, named and labelled as its own are. */
    function wireAuthored(f, box, name, legend) {
      const sel = box.querySelector('select');
      if (sel) {
        f.control = sel;
        if (sel.matches(FP('option-select'))) {
          sel.name = name;
          if (legend) { if (!legend.id) legend.id = uid('legend'); sel.setAttribute('aria-labelledby', legend.id); }
          /* each option's words, without the count the build put after them */
          for (const o of sel.options) {
            if (o.value === '') continue;
            const said = o.textContent;
            f.options.set(o.value, { el: o, input: null, count: null, label: f.counts ? said.replace(/ \(\d+\)$/, '') : said });
          }
        }
        sel.addEventListener('change', () => { f.selected = new Set(sel.value ? [sel.value] : []); update(); });
        return;
      }
      for (const input of box.querySelectorAll('input[type="checkbox"], input[type="radio"]')) {
        const host = input.closest('label') || input;
        /* the build names them by field; two filters over one field are two groups */
        if (host.matches(FP('option'))) input.name = name;
        f.options.set(input.value, { el: host, input, count: host.querySelector(FP('option-count')) });
        input.addEventListener('change', () => toggle(f, input.value, input.checked));
      }
      for (const b of box.querySelectorAll('button')) {
        const v = b.getAttribute('data-value') ?? b.value ?? '';
        b.type = 'button';
        if (!b.hasAttribute('aria-pressed')) b.setAttribute('aria-pressed', 'false');
        f.options.set(v, { el: b, input: null, count: b.querySelector(FP('option-count')) });
        b.addEventListener('click', () => toggle(f, v));
      }
    }

    /* The options, made from the values the rows carry — unless the box holds
       them already, as the build writes them wherever it can. */
    function build(f) {
      const box = [...f.el.querySelectorAll(FP('options'))].find((b) => b.closest(FP('facet')) === f.el);
      if (!box) return;
      if (f.range) { buildRange(f, box); return; }
      const legend = f.el.querySelector('legend');
      const name = 'filter-' + n + '-' + f.key.replace(/[^a-z0-9]+/gi, '-');
      if (box.children.length) { wireAuthored(f, box, name, legend); return; }
      if (legend && !legend.id) legend.id = uid('legend');
      const total = new Map();
      for (const it of info) for (const v of it.values[f.key] || []) total.set(v, (total.get(v) || 0) + 1);
      const values = [...f.labels.keys()];
      if (f.sort === 'count') values.sort((a, b) => (total.get(b) || 0) - (total.get(a) || 0) || byLabel(f.labels)(a, b));
      else if (f.sort !== 'data') values.sort(byLabel(f.labels));

      /* What the script makes wears a class named from the facet's own, so a
         BEM rule reaches it: programme__facet makes programme__facet-option,
         -option-label, -option-count and -select. The first class that is not
         a modifier; with none the parts carry their attributes alone. */
      const base = [...f.el.classList].find((c) => !c.includes('--')) || '';
      const named = (el, part) => { if (base) el.classList.add(base + '-' + part); };

      if (f.type === 'select') {
        const sel = document.createElement('select');
        sel.setAttribute('builder-data-element', 'form-select');
        sel.setAttribute('data-filter-part', 'option-select');
        named(sel, 'select');
        sel.name = name;
        if (legend) sel.setAttribute('aria-labelledby', legend.id);
        sel.append(new Option(f.allLabel, ''));
        for (const v of values) {
          const o = new Option(f.labels.get(v), v);
          sel.append(o);
          f.options.set(v, { el: o, input: null, count: null, label: f.labels.get(v) });
        }
        sel.addEventListener('change', () => { f.selected = new Set(sel.value ? [sel.value] : []); update(); });
        f.control = sel;
        box.append(sel);
        return;
      }

      if (!f.multi) values.unshift('');
      for (const v of values) {
        const label = v === '' ? f.allLabel : f.labels.get(v);
        let opt;
        let input = null;
        if (f.type === 'buttons') {
          opt = document.createElement('button');
          opt.type = 'button';
          opt.setAttribute('aria-pressed', 'false');
          opt.addEventListener('click', () => toggle(f, v));
        } else {
          opt = document.createElement('label');
          input = document.createElement('input');
          input.type = f.multi ? 'checkbox' : 'radio';
          input.name = name;
          input.value = v;
          input.setAttribute('builder-data-element', 'form-check-input');
          input.addEventListener('change', () => toggle(f, v, input.checked));
          opt.append(input);
        }
        opt.setAttribute('builder-data-element', 'filter-option');
        opt.setAttribute('data-filter-part', 'option');
        opt.setAttribute('data-value', v);
        named(opt, 'option');
        const text = document.createElement('span');
        text.setAttribute('data-filter-part', 'option-label');
        named(text, 'option-label');
        text.textContent = label;
        opt.append(text);
        let count = null;
        if (f.counts && v !== '') {
          count = document.createElement('span');
          count.setAttribute('data-filter-part', 'option-count');
          named(count, 'option-count');
          opt.append(count);
        }
        box.append(opt);
        f.options.set(v, { el: opt, input, count, label });
      }
    }

    /* ---- a range ----
       What the rows hold decides what it is: numbers, or days. Anything else
       has no order a from and a to could mean, so the facet offers nothing. */
    const DAY = /^\d{4}-\d{2}-\d{2}/;
    const isNum = (v) => v.trim() !== '' && Number.isFinite(Number(v));
    function buildRange(f, box) {
      const all = info.flatMap((it) => it.values[f.key] || []).filter((v) => v !== '');
      f.kind = all.length && all.every(isNum) ? 'number' : all.length && all.every((v) => DAY.test(v)) ? 'date' : '';
      if (!f.kind) return;
      const vals = f.kind === 'number' ? all.map(Number) : all.map((v) => v.slice(0, 10));
      const lo = vals.reduce((a, b) => (b < a ? b : a));
      const hi = vals.reduce((a, b) => (b > a ? b : a));
      f.lo = String(lo); f.hi = String(hi);
      /* A thumb moves in the data's own precision: whole numbers by one, a
         price written to the cent by a cent — never to the fifteenth place. */
      const places = f.kind === 'number' ? Math.min(4, Math.max(0, ...all.map((v) => (v.split('.')[1] || '').length))) : 0;
      const step = places ? (1 / Math.pow(10, places)).toFixed(places) : '1';
      const legend = f.el.querySelector('legend');
      const name = legend ? legend.textContent.trim() : f.key;

      /* Controls somebody put here are wired as they are: the two fields
         marked from and to, or the first two inputs. */
      let from = box.querySelector(FP('range-from'));
      let to = box.querySelector(FP('range-to'));
      if (!from || !to) [from, to] = [...box.querySelectorAll('input')].filter((i) => i.type !== 'range');
      let thumbs = null;
      if (!from || !to) {
        const wrap = document.createElement('div');
        wrap.setAttribute('builder-data-element', 'filter-range');
        wrap.setAttribute('data-filter-part', 'range');
        if (f.kind === 'number' && f.el.getAttribute('data-facet-range') === 'slider') {
          const slider = document.createElement('div');
          slider.setAttribute('data-filter-part', 'range-slider');
          thumbs = ['from', 'to'].map((end) => {
            const r = document.createElement('input');
            r.type = 'range';
            r.min = f.lo; r.max = f.hi; r.step = step;
            r.value = end === 'from' ? f.lo : f.hi;
            r.setAttribute('data-filter-part', 'range-thumb');
            r.setAttribute('aria-label', name + ', ' + (f.el.getAttribute('data-facet-' + end) || (end === 'from' ? 'From' : 'To')).toLowerCase());
            slider.append(r);
            return r;
          });
          wrap.append(slider);
        }
        const field = (end) => {
          const label = document.createElement('label');
          label.setAttribute('data-filter-part', 'range-field');
          const words = document.createElement('span');
          words.setAttribute('data-filter-part', 'range-label');
          words.textContent = f.el.getAttribute('data-facet-' + end) || (end === 'from' ? 'From' : 'To');
          const input = document.createElement('input');
          input.type = f.kind === 'number' ? 'number' : 'date';
          input.setAttribute('builder-data-element', 'form-input');
          input.setAttribute('data-filter-part', 'range-' + end);
          input.min = f.lo; input.max = f.hi;
          if (f.kind === 'number') { input.step = step; input.placeholder = end === 'from' ? f.lo : f.hi; input.inputMode = places ? 'decimal' : 'numeric'; }
          label.append(words, input);
          return label;
        };
        const sep = document.createElement('span');
        sep.setAttribute('data-filter-part', 'range-sep');
        sep.setAttribute('aria-hidden', 'true');
        sep.textContent = '–';
        const a = field('from');
        const b = field('to');
        wrap.append(a, sep, b);
        box.append(wrap);
        from = a.querySelector('input');
        to = b.querySelector('input');
      }
      f.fields = { from, to, thumbs, slider: thumbs ? thumbs[0].parentNode : null };
      from.value = f.from; to.value = f.to;
      const typed = () => {
        f.from = from.value.trim(); f.to = to.value.trim();
        cancelAnimationFrame(frame);
        frame = requestAnimationFrame(update);
      };
      from.addEventListener('input', typed);
      to.addEventListener('input', typed);
      if (thumbs) {
        /* The thumb that moved may not pass the other: it stops where the
           other one is. Its field follows, and an end at the bound is no
           limit at all, so it is written as nothing. */
        thumbs.forEach((r, k) => r.addEventListener('input', () => {
          const [a, b] = thumbs;
          if (Number(a.value) > Number(b.value)) r.value = k === 0 ? b.value : a.value;
          f.from = a.value === f.lo ? '' : a.value;
          f.to = b.value === f.hi ? '' : b.value;
          from.value = f.from; to.value = f.to;
          cancelAnimationFrame(frame);
          frame = requestAnimationFrame(update);
        }));
      }
    }
    /* The fields, the thumbs and the stretch between them, from the state. */
    function showRange(f) {
      if (!f.fields) return;
      const { from, to, thumbs, slider } = f.fields;
      if (from.value !== f.from && document.activeElement !== from) from.value = f.from;
      if (to.value !== f.to && document.activeElement !== to) to.value = f.to;
      if (!thumbs) return;
      const lo = Number(f.lo);
      const span = Number(f.hi) - lo || 1;
      const clamp = (v, d) => (v === '' || !Number.isFinite(Number(v)) ? d : Math.min(Number(f.hi), Math.max(lo, Number(v))));
      const a = clamp(f.from, lo);
      const b = clamp(f.to, Number(f.hi));
      if (document.activeElement !== thumbs[0]) thumbs[0].value = String(a);
      if (document.activeElement !== thumbs[1]) thumbs[1].value = String(b);
      slider.style.setProperty('--filter-range-from', String((a - lo) / span));
      slider.style.setProperty('--filter-range-to', String((b - lo) / span));
      /* Two thumbs on one spot: the one that can still move is on top. */
      thumbs[0].style.zIndex = a > lo + span / 2 ? '2' : '';
    }

    /* ---- sorting ----
       The rows are put in order where they already stand: each row's place
       is marked, the marks are filled in the new order, so a row never
       leaves its own list and whatever sits between the rows stays put. */
    const NUM = /^-?\d+(\.\d+)?$/;
    function compare(key, desc) {
      return (a, b) => {
        const x = a.by[key];
        const y = b.by[key];
        /* an entry with nothing to sort by goes last, either way round */
        if (!x || !y) return (x ? 0 : 1) - (y ? 0 : 1) || a.i - b.i;
        const c = NUM.test(x) && NUM.test(y) ? Number(x) - Number(y)
          : x.localeCompare(y, undefined, { numeric: true, sensitivity: 'base' });
        return (desc ? -c : c) || a.i - b.i;
      };
    }
    function order() {
      const [key, dir] = sort.split(':');
      const cmp = key ? compare(key, dir === 'desc') : (a, b) => a.i - b.i;
      const lists = new Map();
      for (const it of info) {
        const p = it.el.parentNode;
        if (!p) continue;
        if (!lists.has(p)) lists.set(p, []);
        lists.get(p).push(it);
      }
      for (const [p, items] of lists) {
        const now = items.slice().sort((a, b) => (a.el.compareDocumentPosition(b.el) & 4 ? -1 : 1));
        const next = items.slice().sort(cmp);
        if (now.every((it, k) => it === next[k])) continue;
        const marks = now.map((it) => { const m = document.createComment(''); p.insertBefore(m, it.el); return m; });
        marks.forEach((m, k) => p.replaceChild(next[k].el, m));
      }
    }
    function setSort(v) {
      sort = sorts.some((sel) => [...sel.options].some((o) => o.value === v)) ? v : '';
      for (const sel of sorts) if (sel.value !== sort) sel.value = sort;
      order();
    }

    const paramOf = (f) => f.key.replace(/[^a-z0-9]+/gi, '_');
    function readUrl() {
      const p = new URLSearchParams(location.search);
      const qq = p.get('q');
      if (qq) { q = qq; for (const i of inputs) i.value = qq; }
      for (const f of facets) {
        const raw = p.get(paramOf(f));
        if (!raw) continue;
        if (f.range) {
          const [a = '', b = ''] = raw.split('..');
          f.from = a.trim(); f.to = b.trim();
          continue;
        }
        const vals = raw.split(',').filter(Boolean);
        f.selected = new Set(f.multi ? vals : vals.slice(0, 1));
      }
      const ss = p.get('sort');
      if (ss) sort = ss;
    }
    function writeUrl() {
      const p = new URLSearchParams(location.search);
      if (q.trim()) p.set('q', q.trim()); else p.delete('q');
      for (const f of facets) {
        const v = f.range ? (isOn(f) ? f.from + '..' + f.to : '') : [...f.selected].join(',');
        if (v) p.set(paramOf(f), v); else p.delete(paramOf(f));
      }
      if (sorts.length) { if (sort) p.set('sort', sort); else p.delete('sort'); }
      const s = p.toString();
      const href = location.pathname + (s ? '?' + s : '') + location.hash;
      if (href !== location.pathname + location.search + location.hash) history.replaceState(history.state, '', href);
    }

    function update() {
      const terms = words(q);
      let shown = 0;
      for (const it of info) {
        const ok = textOk(it, terms) && facets.every((f) => facetOk(it, f));
        it.el.hidden = !ok;
        if (ok) shown += 1;
      }
      /* What each option would leave, with the other facets as they are —
         which is what a count beside an option means. */
      for (const f of facets) {
        if (f.range) { showRange(f); continue; }
        const tally = new Map();
        for (const it of info) {
          if (!textOk(it, terms) || !facets.every((g) => g === f || facetOk(it, g))) continue;
          for (const v of it.values[f.key] || []) tally.set(v, (tally.get(v) || 0) + 1);
        }
        for (const [v, o] of f.options) {
          const on = v === '' ? f.selected.size === 0 : f.selected.has(v);
          if (o.input) o.input.checked = on;
          if (o.el.hasAttribute('aria-pressed')) o.el.setAttribute('aria-pressed', on ? 'true' : 'false');
          if (v === '') continue;
          const c = tally.get(v) || 0;
          if (o.count) o.count.textContent = String(c);
          if (o.el.tagName === 'OPTION' && o.label !== undefined) o.el.textContent = o.label + (f.counts ? ' (' + c + ')' : '');
          const dead = c === 0 && !on;
          if (f.empty === 'hide') o.el.hidden = dead;
          else if (f.empty === 'disable') {
            o.el.toggleAttribute('data-filter-disabled', dead);
            if (o.input) o.input.disabled = dead;
            else if ('disabled' in o.el) o.el.disabled = dead;
          }
        }
        if (f.control) f.control.value = [...f.selected][0] || '';
      }
      for (const { el, many } of counts) {
        const one = el.getAttribute('data-count-one');
        const none = el.getAttribute('data-count-none');
        const say = (shown === 0 && none ? none : shown === 1 && one ? one : many).replace(/#/g, String(shown));
        /* the build wrote it already: the same words set again would be read
           out again, the count being a live region */
        if (el.textContent !== say) el.textContent = say;
      }
      for (const e of empties) e.hidden = shown > 0;
      /* A sort narrows nothing, so it neither makes the filter active nor is
         taken away by Clear filters: the order is how somebody reads the
         list, not which of it they want. */
      const active = terms.length > 0 || facets.some(isOn);
      for (const r of resets) r.disabled = !active;
      root.toggleAttribute('data-filter-active', active);
      if (url) writeUrl();
    }

    let frame = 0;
    for (const input of inputs) {
      input.addEventListener('input', () => {
        q = input.value;
        for (const o of inputs) if (o !== input) o.value = q;
        cancelAnimationFrame(frame);
        frame = requestAnimationFrame(update);
      });
      input.addEventListener('keydown', (e) => {
        if (e.key === 'Escape' && input.value) { e.preventDefault(); input.value = ''; q = ''; update(); }
        else if (e.key === 'Enter') e.preventDefault();
      });
    }
    for (const r of resets) {
      r.addEventListener('click', () => {
        q = '';
        for (const i of inputs) i.value = '';
        for (const f of facets) { f.selected.clear(); f.from = ''; f.to = ''; }
        update();
      });
    }
    for (const sel of sorts) sel.addEventListener('change', () => { setSort(sel.value); update(); });
    if (url) readUrl();
    for (const f of facets) build(f);
    /* A select the browser restored on the back button says what it says. */
    setSort(sort || (sorts.find((sel) => sel.value) || { value: '' }).value);
    update();
  }

  /* =========================================================== site search */

  let indexPromise = null;
  const loadIndex = () => indexPromise || (indexPromise = fetch(INDEX_URL, { headers: { accept: 'application/json' } })
    .then((r) => (r.ok ? r.json() : null))
    .then(prepare)
    .catch(() => null));

  function prepare(data) {
    if (!data || !Array.isArray(data.docs)) return null;
    const c = Object.assign({
      match: 'prefix', typos: true, words: 'all', accents: true, minChars: 2, limit: 8, pageLimit: 50,
      excerpt: true, highlight: true, showType: true, page: '', synonyms: [],
      noResults: 'No results for “#”', seeAll: 'See all results', found: '# results',
    }, data.config || {});
    c.weights = Object.assign({ title: 10, description: 4, body: 1, tags: 6 }, c.weights || {});
    c.syn = new Map();
    for (const group of c.synonyms || []) {
      const ws = [...new Set(group.flatMap((x) => words(x, c.accents)).filter((w) => w.length > 1))];
      for (const w of ws) c.syn.set(w, ws);
    }
    const docs = data.docs.map((d) => {
      const fields = [
        ['title', d.t || ''], ['description', d.d || ''], ['body', d.b || ''], ['tags', (d.g || []).join(' ')],
      ].map(([name, text]) => ({ w: c.weights[name] || 0, words: [...new Set(words(text, c.accents))] }));
      return { url: d.u, title: d.t || d.u, desc: d.d || '', body: d.b || '', type: d.k || '', tags: d.g || [], image: d.i || '', fields, folded: fold(d.t || '', c.accents) };
    });
    return { config: c, docs };
  }

  /* What a forgiven typo counts for — below every match as typed. */
  const FUZZY = 0.3;

  /* Edits between two words, giving up once it is past max. */
  function lev(a, b, max) {
    if (Math.abs(a.length - b.length) > max) return max + 1;
    let prev = Array.from({ length: b.length + 1 }, (_, i) => i);
    for (let i = 1; i <= a.length; i += 1) {
      const cur = [i];
      let best = i;
      for (let j = 1; j <= b.length; j += 1) {
        cur[j] = Math.min(prev[j] + 1, cur[j - 1] + 1, prev[j - 1] + (a[i - 1] === b[j - 1] ? 0 : 1));
        if (cur[j] < best) best = cur[j];
      }
      if (best > max) return max + 1;
      prev = cur;
    }
    return prev[b.length];
  }

  /* How well a typed word (or one of its synonyms) meets the words of a field. */
  function strength(fieldWords, alts, c) {
    let best = 0;
    for (const t of alts) {
      for (const w of fieldWords) {
        let s = 0;
        if (w === t) s = 1;
        else if (c.match !== 'exact' && w.startsWith(t)) s = 0.75;
        else if (c.match === 'contains' && w.includes(t)) s = 0.45;
        if (s > best) { best = s; if (best === 1) return 1; }
      }
    }
    if (best || !c.typos) return best;
    /* A typo is forgiven in the word as typed, not in its synonyms — a
       synonym is a word somebody chose, and a near miss of it is a guess
       about a guess. A word half typed is forgiven from five letters, since
       four letters with one wrong is the start of half the dictionary. */
    const t = alts[0];
    if (t.length < 4) return 0;
    const max = t.length >= 8 ? 2 : 1;
    for (const w of fieldWords) {
      if (lev(t, w, max) <= max) return FUZZY;
      if (t.length >= 5 && c.match !== 'exact' && w.length > t.length && lev(t, w.slice(0, t.length), max) <= max) return FUZZY * 0.8;
    }
    return 0;
  }

  function search(index, query, limit) {
    const c = index.config;
    const qn = fold(query, c.accents).trim();
    const terms = words(query, c.accents);
    if (qn.length < c.minChars || !terms.length) return { terms: [], hits: [], total: 0 };
    const groups = terms.map((t) => (c.syn.has(t) ? [...new Set([t, ...c.syn.get(t)])] : [t]));
    const hits = [];
    for (const d of index.docs) {
      let score = 0;
      let matched = 0;
      let guessed = true;
      for (const alts of groups) {
        let s = 0;
        let best = 0;
        for (const f of d.fields) {
          if (!f.w) continue;
          const m = strength(f.words, alts, c);
          s += f.w * m;
          if (m > best) best = m;
        }
        if (s > 0) { matched += 1; score += s; if (best > FUZZY) guessed = false; }
        else if (c.words !== 'any') { matched = 0; break; }
      }
      if (!matched) continue;
      /* the whole phrase in the title is the best answer there is */
      if (d.folded.includes(qn)) { score += c.weights.title * 2; guessed = false; }
      hits.push({ d, score, guessed });
    }
    /* A typo is forgiven where nothing matches as typed: a page that only a
       guess found is a result nobody asked for beside one that is exactly
       what was typed. */
    const sure = hits.filter((h) => !h.guessed);
    const kept = sure.length ? sure : hits;
    kept.sort((a, b) => b.score - a.score);
    return { terms: groups.flat(), hits: kept.slice(0, limit), total: kept.length };
  }

  /* Where the terms are in a text, over the text as written. */
  function spans(text, terms, c) {
    let folded = '';
    const map = [];
    for (let i = 0; i < text.length; i += 1) {
      const f = fold(text[i], c.accents);
      for (let k = 0; k < f.length; k += 1) { folded += f[k]; map.push(i); }
    }
    map.push(text.length);
    const out = [];
    for (const t of terms) {
      if (!t) continue;
      let at = folded.indexOf(t);
      while (at !== -1) {
        if (c.match === 'contains' || at === 0 || !LETTER.test(folded[at - 1])) out.push([map[at], map[at + t.length - 1] + 1]);
        at = folded.indexOf(t, at + t.length);
      }
    }
    out.sort((a, b) => a[0] - b[0]);
    const merged = [];
    for (const s of out) {
      const last = merged[merged.length - 1];
      if (last && s[0] <= last[1]) last[1] = Math.max(last[1], s[1]);
      else merged.push(s.slice());
    }
    return merged;
  }
  const marked = (text, sp) => {
    let html = '';
    let at = 0;
    for (const [a, b] of sp) { html += esc(text.slice(at, a)) + '<mark>' + esc(text.slice(a, b)) + '</mark>'; at = b; }
    return html + esc(text.slice(at));
  };
  function excerpt(d, terms, c) {
    let source = d.body;
    let sp = source ? spans(source, terms, c) : [];
    if (!sp.length && d.desc) { source = d.desc; sp = spans(source, terms, c); }
    if (!source) return '';
    let start = sp.length ? Math.max(0, sp[0][0] - 50) : 0;
    if (start > 0) { const s = source.indexOf(' ', start); if (s !== -1 && s - start < 24) start = s + 1; }
    let end = Math.min(source.length, start + 190);
    if (end < source.length) { const e = source.lastIndexOf(' ', end); if (e > start + 60) end = e; }
    const piece = source.slice(start, end);
    const local = sp.filter(([a, b]) => a >= start && b <= end).map(([a, b]) => [a - start, b - start]);
    return (start > 0 ? '… ' : '') + (c.highlight ? marked(piece, local) : esc(piece)) + (end < source.length ? ' …' : '');
  }

  function initSearch(root) {
    if (root.hasAttribute('data-search-ready')) return;
    const scope = root.getAttribute('data-search-scope');
    if (scope === 'list' || (root.closest(FP('filter')) && scope !== 'site')) return;
    root.setAttribute('data-search-ready', '');
    const input = root.querySelector(SP('input')) || root.querySelector('input');
    if (!input) return;
    const results = root.querySelector(SP('results'));
    const page = !!results && results.getAttribute('data-search-display') === 'page';
    /* The Result row you designed, taken out and kept: it is what every hit is
       a copy of. Without one the script writes the same markup itself. */
    const designed = results ? results.querySelector(SP('hit')) : null;
    const design = designed ? designed.cloneNode(true) : null;
    if (designed) designed.remove();

    /* One copy of the row, every {result.…} filled: in text, the title and the
       excerpt as markup (the words found are marked) and the rest as text; in
       an attribute — parked as data-result-<name> by the emitter — as text. A
       picture with no address takes its element with it, and a part a field
       left empty is taken out, so a row never shows an empty box. */
    function fillRow(d, titleHtml, excerptHtml, c) {
      const el = design.cloneNode(true);
      el.removeAttribute('hidden');
      const text = { title: d.title, url: d.url, type: c.showType ? d.type : '', excerpt: '', description: d.desc, tags: d.tags.join(', '), image: d.image };
      const rich = { title: titleHtml, excerpt: excerptHtml };
      const TOKEN = /\{\s*result\.([a-z]+)\s*\}/g;
      for (const node of [el, ...el.querySelectorAll('*')]) {
        for (const a of [...node.attributes]) {
          const parked = a.name.indexOf('data-result-') === 0;
          if (!parked && a.value.indexOf('{') < 0) continue;
          const name = parked ? a.name.slice(12) : a.name;
          const v = a.value.replace(TOKEN, (_, k) => (text[k] == null ? '' : String(text[k])));
          if (parked) node.removeAttribute(a.name);
          if (name === 'src' && !v.trim()) { node.setAttribute('data-result-gone', ''); continue; }
          node.setAttribute(name, v);
        }
      }
      for (const gone of el.querySelectorAll('[data-result-gone]')) gone.remove();
      const texts = [];
      const walker = document.createTreeWalker(el, NodeFilter.SHOW_TEXT);
      while (walker.nextNode()) if (walker.currentNode.nodeValue.indexOf('{') >= 0) texts.push(walker.currentNode);
      for (const t of texts) {
        const tpl = document.createElement('template');
        tpl.innerHTML = esc(t.nodeValue).replace(TOKEN, (_, k) => (k in rich ? rich[k] : esc(text[k] == null ? '' : text[k])));
        t.replaceWith(tpl.content);
      }
      for (const part of el.querySelectorAll('[data-search-part^="hit-"]')) {
        if (part.matches('img, svg, video') || part.textContent.trim() || part.querySelector('img, svg, video')) continue;
        part.remove();
      }
      el.id = uid('hit');
      el.setAttribute('data-search-part', 'hit');
      if (!page) { el.setAttribute('role', 'option'); el.setAttribute('aria-selected', 'false'); el.setAttribute('tabindex', '-1'); }
      return el;
    }
    const button = root.querySelector(SP('submit'));
    if (results && !page) {
      if (!results.id) results.id = uid('results');
      input.setAttribute('role', 'combobox');
      input.setAttribute('aria-autocomplete', 'list');
      input.setAttribute('aria-expanded', 'false');
      input.setAttribute('aria-controls', results.id);
      results.setAttribute('role', 'listbox');
      if (!results.hasAttribute('aria-label')) results.setAttribute('aria-label', 'Search results');
    }
    if (page && results) { results.hidden = false; results.setAttribute('aria-live', 'polite'); }

    let active = -1;
    let timer = 0;
    const hitsIn = () => (results ? [...results.querySelectorAll(SP('hit'))] : []);
    const open = (on) => {
      if (!results || page) return;
      results.hidden = !on;
      input.setAttribute('aria-expanded', on ? 'true' : 'false');
      root.toggleAttribute('data-search-open', on);
      if (!on) setActive(-1);
    };
    /* -1 is the field itself: up from the first result goes back to it. */
    function setActive(i) {
      const links = hitsIn();
      active = !links.length || i < 0 ? -1 : i % links.length;
      links.forEach((a, k) => a.setAttribute('aria-selected', k === active ? 'true' : 'false'));
      if (active >= 0) {
        input.setAttribute('aria-activedescendant', links[active].id);
        links[active].scrollIntoView({ block: 'nearest' });
      } else input.removeAttribute('aria-activedescendant');
    }
    const syncUrl = (query) => {
      const p = new URLSearchParams(location.search);
      if (query.trim()) p.set('q', query.trim()); else p.delete('q');
      const s = p.toString();
      history.replaceState(history.state, '', location.pathname + (s ? '?' + s : '') + location.hash);
    };

    async function run() {
      const query = input.value;
      if (page) syncUrl(query);
      if (!results) return;
      const index = await loadIndex();
      if (query !== input.value) return;
      if (!index) {
        results.innerHTML = '<p data-search-part="none">Search is not available right now.</p>';
        open(true);
        return;
      }
      const c = index.config;
      const r = search(index, query, page ? c.pageLimit : c.limit);
      if (!r.terms.length) { results.innerHTML = ''; open(false); return; }
      const say = (s, v) => esc(String(s).replace(/#/g, v));
      const rows = r.hits.map((h) => {
        const d = h.d;
        const title = c.highlight ? marked(d.title, spans(d.title, r.terms, c)) : esc(d.title);
        const x = c.excerpt ? excerpt(d, r.terms, c) : '';
        if (design) return fillRow(d, title, x, c);
        return '<a href="' + esc(d.url) + '" id="' + uid('hit') + '" data-search-part="hit"'
          + (page ? '' : ' role="option" aria-selected="false" tabindex="-1"') + '>'
          + '<span data-search-part="hit-title">' + title + '</span>'
          + (c.showType && d.type ? '<span data-search-part="hit-type">' + esc(d.type) + '</span>' : '')
          + (x ? '<span data-search-part="hit-excerpt">' + x + '</span>' : '')
          + '</a>';
      });
      const none = r.hits.length ? '' : '<p data-search-part="none">' + say(c.noResults, query.trim()) + '</p>';
      const summary = page && r.hits.length ? '<p data-search-part="summary">' + say(c.found, r.total) + '</p>' : '';
      const all = !page && c.page && r.hits.length
        ? '<a data-search-part="all" href="' + esc(c.page + '?q=' + encodeURIComponent(query.trim())) + '">'
          + esc(c.seeAll) + (r.total > r.hits.length ? ' (' + r.total + ')' : '') + '</a>'
        : '';
      results.textContent = '';
      results.append(markup(summary), ...rows.map((x) => (typeof x === 'string' ? markup(x) : x)), markup(none + all));
      active = -1;
      open(true);
    }

    async function go() {
      const query = input.value.trim();
      if (!query) return;
      if (page) { run(); return; }
      const links = hitsIn();
      if (active >= 0 && links[active]) { location.assign(hrefOf(links[active])); return; }
      const index = await loadIndex();
      if (index && index.config.page) { location.assign(index.config.page + '?q=' + encodeURIComponent(query)); return; }
      if (!links.length) await run();
      const first = hitsIn()[0];
      if (first && hrefOf(first)) location.assign(hrefOf(first));
    }

    input.addEventListener('input', () => { clearTimeout(timer); timer = setTimeout(run, 110); });
    input.addEventListener('focus', () => { loadIndex(); if (!page && input.value.trim() && results && results.innerHTML) open(true); });
    input.addEventListener('keydown', (e) => {
      const isOpen = !!results && !results.hidden && !page;
      if (e.key === 'Enter') { e.preventDefault(); go(); }
      else if (e.key === 'ArrowDown' && !page) {
        e.preventDefault();
        if (!isOpen && input.value.trim()) run(); else setActive(active + 1);
      } else if (e.key === 'ArrowUp' && isOpen) { e.preventDefault(); setActive(active === -1 ? hitsIn().length - 1 : active - 1); }
      else if (e.key === 'Escape') {
        if (isOpen) { e.preventDefault(); open(false); }
        else if (input.value) { e.preventDefault(); input.value = ''; if (page) run(); }
      }
    });
    if (button) button.addEventListener('click', (e) => { e.preventDefault(); go(); });
    if (results && !page) {
      /* A press on a result must not take the focus away first, or the list
         closes under the click. */
      results.addEventListener('mousedown', (e) => { if (e.target.closest(SP('hit'))) e.preventDefault(); });
      document.addEventListener('pointerdown', (e) => { if (!root.contains(e.target)) open(false); });
      root.addEventListener('focusout', () => setTimeout(() => { if (!root.contains(document.activeElement)) open(false); }, 0));
    }

    const key = root.getAttribute('data-search-shortcut');
    if (key) {
      document.addEventListener('keydown', (e) => {
        if (key === '/' && e.key === '/' && !e.metaKey && !e.ctrlKey && !e.altKey && !typing(document.activeElement)) {
          e.preventDefault(); input.focus();
        } else if (key === 'k' && (e.metaKey || e.ctrlKey) && String(e.key).toLowerCase() === 'k') {
          e.preventDefault(); input.focus(); input.select();
        }
      });
    }

    if (page) {
      const qp = new URLSearchParams(location.search).get('q');
      if (qp) { input.value = qp; run(); }
    }
  }

  const scan = (scope) => {
    const at = scope || document;
    try {
      for (const root of at.querySelectorAll(FP('filter'))) initFilter(root);
    } finally {
      /* the head's first answer to an address that has chosen already is
         this script's from here on — and lifted however this pass ended */
      document.documentElement.removeAttribute('data-filter-armed');
    }
    for (const root of at.querySelectorAll(SP('search'))) initSearch(root);
  };
  if (document.readyState === 'loading') addEventListener('DOMContentLoaded', () => scan());
  else scan();
  window.__siterealSearch = { scan, load: loadIndex };
})();
